let menuItems=[];async function loadProducts(){try{const response=await fetch("product_data.json");if(!response.ok){throw new Error("Failed to load products")}menuItems=await response.json();return menuItems}catch(error){console.error("Error loading products:",error);return[]}}async function initializeProducts(){console.log("Initializing products...");const spinner=document.getElementById("loadingSpinner");if(spinner)spinner.classList.remove("hidden");const products=await loadProducts();console.log("Loaded products:",products.length);if(spinner)spinner.style.display="none";displayProducts(products);console.log("Products initialized")}function generateCategoryTabs(){}function setActiveTab(event){for(const btn of document.querySelectorAll(".tab-button")){btn.classList.remove("active")}event.target.classList.add("active");const category=event.target.dataset.category;const select=document.getElementById("categorySelect");if(select)select.value=category;filterAndDisplay()}function getCurrentCategory(){const activeBtn=document.querySelector(".filter-cat-btn.active");return activeBtn?.dataset?.filterCategory??"all"}function displayProducts(products){console.log("Displaying products:",products.length);const grid=document.getElementById("productsGrid");console.log("Grid found:",!!grid);grid.innerHTML="";const productsByCategory={};for(const item of products){if(!productsByCategory[item.category])productsByCategory[item.category]=[];productsByCategory[item.category].push(item)}const categoryOrder=["Cookie"];const otherCategories=Object.keys(productsByCategory).filter(cat=>cat!=="Cookie").sort((a,b)=>a.localeCompare(b));const sortedCategories=[...categoryOrder,...otherCategories];let globalIndex=0;let isFirstAccordion=true;for(const category of sortedCategories){const items=productsByCategory[category];if(items&&items.length>0){const accordion=createAccordionSection(category,items,globalIndex,isFirstAccordion);grid.appendChild(accordion.node);globalIndex=accordion.nextIndex;isFirstAccordion=false}}console.log("Products displayed")}function pluralizeCategoryName(category){const pluralMap={Cookie:"Cookies",Bread:"Breads",Brownie:"Brownies",Cake:"Cakes",Candy:"Candies",Muffin:"Muffins",Pastry:"Pastries",Pie:"Pies"};return pluralMap[category]||category}function createCookieSubAccordions(content,items,startIndex){const subcategories=["simple","fancy","complex"];let index=startIndex;for(const sub of subcategories){const subItems=items.filter(item=>item.subcategory===sub);if(subItems.length>0){const subAccordion=document.createElement("div");subAccordion.className="sub-accordion-section";const subHeader=document.createElement("button");subHeader.className="sub-accordion-header";subHeader.setAttribute("aria-expanded","false");const subLabel=sub.charAt(0).toUpperCase()+sub.slice(1);subHeader.innerHTML=`\n        <span class="sub-accordion-title">${subLabel} Cookies <span class="accordion-count">(${subItems.length})</span></span>\n        <svg class="accordion-icon" width="16" height="16" viewBox="0 0 20 20" fill="none">\n          <path d="M5 7.5L10 12.5L15 7.5" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>\n        </svg>\n      `;const subContent=document.createElement("div");subContent.className="sub-accordion-content";const grid=document.createElement("div");grid.className="accordion-grid";for(const item of subItems){const thumb=createProductThumbnail(item,index);grid.appendChild(thumb);index++}subContent.appendChild(grid);subAccordion.appendChild(subHeader);subAccordion.appendChild(subContent);content.appendChild(subAccordion);subHeader.onclick=()=>toggleAccordion(subHeader,subContent)}}return index}function createAccordionSection(category,items,startIndex,isFirstAccordion=false){const accordion=document.createElement("div");accordion.className="accordion-section";const header=document.createElement("button");header.className="accordion-header";header.setAttribute("aria-expanded",isFirstAccordion?"true":"false");const pluralCategory=pluralizeCategoryName(category);header.innerHTML=`\n    <span class="accordion-title">${pluralCategory} <span class="accordion-count">(${items.length})</span></span>\n    <svg class="accordion-icon" width="20" height="20" viewBox="0 0 20 20" fill="none">\n      <path d="M5 7.5L10 12.5L15 7.5" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>\n    </svg>\n  `;const content=document.createElement("div");content.className=isFirstAccordion?"accordion-content open":"accordion-content";let index=startIndex;if(category==="Cookie"){index=createCookieSubAccordions(content,items,startIndex)}else{const grid=document.createElement("div");grid.className="accordion-grid";for(const item of items){const thumb=createProductThumbnail(item,index);grid.appendChild(thumb);index++}content.appendChild(grid)}accordion.appendChild(header);accordion.appendChild(content);header.onclick=()=>toggleAccordion(header,content);return{node:accordion,nextIndex:index}}function toggleAccordion(header,content){const isOpen=content.classList.contains("open");if(isOpen){content.classList.remove("open");header.setAttribute("aria-expanded","false")}else{content.classList.add("open");header.setAttribute("aria-expanded","true")}}function createProductThumbnail(item,index){const thumb=document.createElement("div");thumb.className="product-thumbnail";thumb.onclick=()=>openProductModal(menuItems.indexOf(item));const imgWrap=document.createElement("div");imgWrap.className="thumbnail-image";if(item.image){const img=document.createElement("img");img.src=item.image.replace(/\\/g,"/");img.alt=item.name||"Product Image";img.loading="lazy";imgWrap.appendChild(img)}else{imgWrap.innerHTML='<div class="image-placeholder">Image Coming Soon</div>'}thumb.appendChild(imgWrap);const nameDiv=document.createElement("div");nameDiv.className="thumbnail-name";nameDiv.textContent=item.name;thumb.appendChild(nameDiv);const priceDiv=document.createElement("div");priceDiv.className="thumbnail-price";const defaultPrice=getDefaultPrice(item);priceDiv.textContent=`Starting at $${defaultPrice.toFixed(2)}`;thumb.appendChild(priceDiv);return thumb}function createProductCard(item,index){const defaultPrice=getDefaultPrice(item);const card=document.createElement("div");card.className="product-grid-card";card.onclick=()=>openProductModal(menuItems.indexOf(item));const imgWrap=document.createElement("div");imgWrap.className="product-image";if(item.image){const img=document.createElement("img");img.src=item.image.replace(/\\/g,"/");img.alt=item.name||"Product Image";img.loading="lazy";imgWrap.appendChild(img)}else{imgWrap.innerHTML='<div class="image-placeholder">Image Coming Soon</div>'}card.appendChild(imgWrap);const info=document.createElement("div");info.className="product-info";const nameDiv=document.createElement("div");nameDiv.className="product-name";nameDiv.textContent=item.name;info.appendChild(nameDiv);const priceDiv=document.createElement("div");priceDiv.className="product-price";priceDiv.textContent=`from $${defaultPrice.toFixed(2)}`;info.appendChild(priceDiv);const badges=document.createElement("div");badges.className="dietary-badges";if(item.canGlutenfree){const gfBadge=document.createElement("span");gfBadge.className="badge gluten-free";gfBadge.textContent="🌾 CAN BE GF";badges.appendChild(gfBadge)}if(item.canSugarfree){const sfBadge=document.createElement("span");sfBadge.className="badge sugar-free";sfBadge.textContent="🍬 CAN BE SF";badges.appendChild(sfBadge)}info.appendChild(badges);card.appendChild(info);return card}function getDefaultPrice(item){if(typeof item.basePrice==="number")return item.basePrice;if(item.sizes&&item.sizes.length>0&&item.sizePrice){const firstSize=item.sizes[0];return item.sizePrice[firstSize.replaceAll(" ","_")]||0}return 0}function updatePrice(index){const item=menuItems[index];const cards=document.querySelectorAll(".product-card");const card=cards[index];const sizeSelect=card.querySelector(".size-select");const priceDisplay=card.querySelector(".product-price");const selectedSize=sizeSelect.value.replaceAll(" ","_");const price=item.sizePrice[selectedSize]||item.basePrice;priceDisplay.textContent=`from $${price.toFixed(2)}`}function applyCategoryFilter(items,category){if(category==="all")return items;return items.filter(item=>item.category===category)}function applySearchFilter(items,searchQuery){if(!searchQuery)return items;const query=searchQuery.toLowerCase();return items.filter(item=>item.name.toLowerCase().includes(query))}function applyDietaryFilters(items,gfChecked,sfChecked){if(!gfChecked&&!sfChecked)return items;return items.filter(item=>{if(gfChecked&&item.canGlutenfree)return true;if(sfChecked&&item.canSugarfree)return true;return false})}function sortProducts(items,sortBy){const sorted=items.slice();sorted.sort((a,b)=>{if(sortBy==="name")return a.name.localeCompare(b.name);const priceA=getDefaultPrice(a);const priceB=getDefaultPrice(b);if(sortBy==="price-low")return priceA-priceB;if(sortBy==="price-high")return priceB-priceA;return 0});return sorted}function filterAndDisplay(){let filtered=menuItems.slice();const category=getCurrentCategory();filtered=applyCategoryFilter(filtered,category);const searchQuery=document.getElementById("productSearch").value;filtered=applySearchFilter(filtered,searchQuery);const gfFilter=document.getElementById("filter-gf")?.checked;const sfFilter=document.getElementById("filter-sf")?.checked;filtered=applyDietaryFilters(filtered,gfFilter,sfFilter);const sortBy=document.getElementById("productSort").value;filtered=sortProducts(filtered,sortBy);displayProducts(filtered)}function setupModalAccessibility(modal,modalContent){const nameEl=modalContent.querySelector(".product-name");if(nameEl)nameEl.id="modalTitle";setTimeout(()=>{const first=modalContent.querySelector("button, [href], input, select, textarea");(first||modal).focus()},0)}function createModalKeyHandler(modal,modalContent){return e=>{if(e.key==="Escape"){closeProductModal();return}if(e.key==="Tab"){handleModalTabKey(e,modalContent)}}}function handleModalTabKey(e,modalContent){const focusable=Array.from(modalContent.querySelectorAll("button, [href], input, select, textarea"));if(!focusable.length)return;const idx=focusable.indexOf(document.activeElement);if(e.shiftKey&&idx===0){e.preventDefault();focusable.at(-1).focus()}else if(!e.shiftKey&&idx===focusable.length-1){e.preventDefault();focusable[0].focus()}}function openProductModal(index){globalThis.currentModalIndex=index;const item=menuItems[index];const modalContent=document.getElementById("modalContent");modalContent.innerHTML=createModalContent(item,index);const modalImg=modalContent.querySelector(".product-image img");if(modalImg?.dataset?.src){modalImg.src=modalImg.dataset.src}const modal=document.getElementById("productModal");modal.addEventListener("click",handleBackdropClick);setupModalAccessibility(modal,modalContent);const keyHandler=createModalKeyHandler(modal,modalContent);modal.addEventListener("keydown",keyHandler);modal._keyHandler=keyHandler;modal.showModal()}function closeProductModal(){const modal=document.getElementById("productModal");modal.removeEventListener("click",handleBackdropClick);if(modal._keyHandler){modal.removeEventListener("keydown",modal._keyHandler);delete modal._keyHandler}modal.close();document.getElementById("modalContent").innerHTML=""}function handleBackdropClick(e){if(e.target===this)closeProductModal()}function stopModalPropagation(e){e.stopPropagation()}function createModalImage(item){let html='<div class="product-image">';if(item.image){const imagePath=item.image.replace(/\\/g,"/");html+=`<img src="${imagePath}" alt="${item.name||"Product Image"}" loading="lazy">`}else{html+='<div class="image-placeholder">Image Coming Soon</div>'}html+="</div>";return html}function createModalHeader(item,defaultPrice){let html='<div class="product-header">';html+=`<div class="product-name">${item.name}</div>`;html+=`<div class="product-price">Starting at $${defaultPrice.toFixed(2)}</div>`;html+="</div>";return html}function createModalBadges(item){let html='<div class="dietary-badges">';if(item.canGlutenfree){html+='<span class="badge gluten-free">Can be Gluten Free</span>'}if(item.canSugarfree){html+='<span class="badge sugar-free">Can be Sugar Free</span>'}if(item.canShip){html+='<span class="badge shippable">📦 Shippable</span>'}html+="</div>";return html}function createDietaryNotes(item){if(!item.dietaryNotes)return"";let html='<div class="dietary-notes">';html+=`<p class="notes-text">${item.dietaryNotes}</p>`;html+="</div>";return html}function createAllergenWarnings(item){if(!item.allergens||item.allergens.length===0)return"";let html='<div class="allergen-warnings">';html+='<span class="allergen-label">⚠️ Contains: </span>';html+=`<span class="allergen-list">${item.allergens.join(", ")}</span>`;html+="</div>";return html}function createDepositMessage(item){if(!item.hasDeposit||!item.depositAmount)return"";let html='<div class="deposit-message">';html+=`<span class="deposit-icon">🍽️</span> Includes $${item.depositAmount.toFixed(2)} refundable dish deposit`;html+="</div>";return html}function createSizeSelector(item){let html='<div class="form-group">';html+='<label for="modal-size">Size:</label>';html+='<select id="modal-size" class="size-select" onchange="updatePriceInModal()">';for(const size of item.sizes){html+=`<option value="${size}">${size}</option>`}html+="</select>";html+="</div>";return html}function createFlavorSelector(item){if(!item.flavors||item.flavors.length===0)return"";let html='<div class="form-group">';html+='<label for="modal-flavor">Flavor:</label>';html+='<select id="modal-flavor" class="flavor-select" onchange="updateDietaryOptionsInModal()">';for(const flavor of item.flavors){html+=`<option value="${flavor}">${flavor}</option>`}html+="</select>";html+="</div>";return html}function createFlavorNotes(item){if(!item.flavorNotes)return"";let html='<div class="form-group">';html+='<label for="modal-notes">Flavor Notes:</label>';html+='<input type="text" id="modal-notes" class="flavor-notes" placeholder="Optional flavor preferences">';html+="</div>";return html}function createQuantityInput(){let html='<div class="form-group">';html+='<label for="modal-qty">Quantity:</label>';html+='<input type="number" id="modal-qty" class="quantity-input" min="1" value="1">';html+="</div>";return html}function createSpecialOptions(item){if(!item.canGlutenfree&&!item.canSugarfree&&!item.canGiftWrap)return"";let html='<div class="form-group dietary-options">';html+="<label>Special Options:</label>";if(item.canGlutenfree){html+='<label class="checkbox-label"><input type="checkbox" id="modal-gf" class="dietary-checkbox"> Gluten Free</label>'}if(item.canSugarfree){html+='<label class="checkbox-label"><input type="checkbox" id="modal-sf" class="dietary-checkbox"> Sugar Free</label>'}if(item.canGiftWrap){html+=`<label class="checkbox-label"><input type="checkbox" id="modal-gift" class="gift-checkbox" onchange="updatePriceInModal()"> 🎁 Gift Wrap (Mason Jar) +$${item.giftWrapPrice}</label>`}html+="</div>";return html}function createCustomizations(item){if(!item.customizations||item.customizations.length===0)return"";let html='<div class="customizations-section">';for(let i=0;i<item.customizations.length;i++){const customization=item.customizations[i];const groupId=`customization-${i}`;html+=`<div class="form-group customization-group" data-customization-index="${i}">`;html+=`<label class="customization-label">${customization.label}${customization.required?' <span class="required">*</span>':' <span class="optional">(optional)</span>'}</label>`;if(customization.selectionType==="single"){html+='<div class="customization-options radio-group">';if(!customization.required){html+=`<label class="radio-label">\n          <input type="radio" name="${groupId}" value="" checked onchange="updatePriceInModal()">\n          <span class="radio-text">None</span>\n        </label>`}for(let j=0;j<customization.options.length;j++){const option=customization.options[j];const isDefault=option.default===true;const priceModifier=option.price>0?` (+$${option.price.toFixed(2)})`:"";html+=`<label class="radio-label">\n          <input type="radio" name="${groupId}" value="${option.name}" \n            data-price="${option.price||0}"\n            ${isDefault&&customization.required?"checked":""}\n            onchange="updatePriceInModal()">\n          <span class="radio-text">${option.name}${priceModifier}</span>\n        </label>`}html+="</div>"}else if(customization.selectionType==="multiple"){html+='<div class="customization-options checkbox-group">';for(let j=0;j<customization.options.length;j++){const option=customization.options[j];const isDefault=option.default===true;const priceModifier=option.price>0?` (+$${option.price.toFixed(2)})`:"";html+=`<label class="checkbox-label">\n          <input type="checkbox" name="${groupId}" value="${option.name}"\n            data-price="${option.price||0}"\n            ${isDefault?"checked":""}\n            onchange="updatePriceInModal()">\n          <span class="checkbox-text">${option.name}${priceModifier}</span>\n        </label>`}html+="</div>"}html+="</div>"}html+="</div>";return html}function createModalContent(item,index){const defaultPrice=getDefaultPrice(item);let html=createModalImage(item);html+=createModalHeader(item,defaultPrice);html+=createModalBadges(item);html+=createDietaryNotes(item);html+=createAllergenWarnings(item);html+=createDepositMessage(item);html+='<div class="product-form">';html+=createSizeSelector(item);html+=createCustomizations(item);html+=createFlavorSelector(item);html+=createFlavorNotes(item);html+=createQuantityInput();html+=createSpecialOptions(item);html+=`<button class="add-to-cart-btn" onclick="addToCart(${index})">Add to Cart</button>`;html+="</div>";return html}function updatePriceInModal(){const sizeSelect=document.getElementById("modal-size");const giftCheckbox=document.getElementById("modal-gift");const priceDisplay=document.querySelector("#modalContent .product-price");if(!sizeSelect||!priceDisplay)return;const selectedSize=sizeSelect.value.replaceAll(" ","_");const currentItem=menuItems[globalThis.currentModalIndex];let price=currentItem.sizePrice[selectedSize]||currentItem.basePrice||0;if(giftCheckbox?.checked&&currentItem.canGiftWrap){price+=currentItem.giftWrapPrice}if(currentItem.hasDeposit&&currentItem.depositAmount){price+=currentItem.depositAmount}const customizationGroups=document.querySelectorAll(".customization-group");for(const group of customizationGroups){const selectedRadio=group.querySelector('input[type="radio"]:checked');if(selectedRadio&&selectedRadio.dataset.price){price+=parseFloat(selectedRadio.dataset.price)||0}const selectedCheckboxes=group.querySelectorAll('input[type="checkbox"]:checked');for(const checkbox of selectedCheckboxes){if(checkbox.dataset.price){price+=parseFloat(checkbox.dataset.price)||0}}}priceDisplay.textContent=`$${price.toFixed(2)}`}function updateDietaryOptionsInModal(){}globalThis.openProductModal=openProductModal;globalThis.closeProductModal=closeProductModal;globalThis.updatePriceInModal=updatePriceInModal;globalThis.updateDietaryOptionsInModal=updateDietaryOptionsInModal;globalThis.filterAndDisplay=filterAndDisplay;document.addEventListener("DOMContentLoaded",initializeProducts);